contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address u) public payable {
        uint256 beforeU = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint256 beforeContract = address(c).balance;
        bool reverted;
        uint256 returned;
        uint256 v = c.getBalance(u); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            returned = v;
        }
        assert(!reverted && returned == beforeU && returned <= address(c).balance + beforeContract - beforeContract);
    }
}

